// ═══ BLOCKED: waiting for monitor lock ═══
Object vault = new Object();

// Thread-1 holds the lock:
Thread t1 = new Thread(() -> {
    synchronized (vault) {          // acquires lock
        try { Thread.sleep(5000); } // holds lock for 5 seconds
        catch (InterruptedException e) { }
    }
});

// Thread-2 tries to enter the SAME synchronized block:
Thread t2 = new Thread(() -> {
    synchronized (vault) {          // BLOCKED! vault lock held by t1!
        System.out.println("Got the lock!");
    }
});

t1.start();
Thread.sleep(100);
t2.start();
Thread.sleep(100);
t2.getState();  // BLOCKED — waiting for vault lock held by t1
// When t1 exits synchronized → t2 automatically enters → RUNNABLE

// ═══ WAITING: voluntary wait for signal ═══
Thread t3 = new Thread(() -> {
    synchronized (vault) {
        try { vault.wait(); }       // RELEASES lock + enters WAITING
        catch (InterruptedException e) { }
        System.out.println("Woke up!");
    }
});

t3.start();
Thread.sleep(100);
t3.getState();  // WAITING — voluntarily waiting for notify()
// t3 released the vault lock! Other threads CAN enter synchronized(vault)

// Wake up t3:
synchronized (vault) { vault.notify(); }
// t3 moves: WAITING → must reacquire lock → BLOCKED (if lock held) → RUNNABLE

// ═══ KEY DIFFERENCES ═══
// BLOCKED:                              WAITING:
// Involuntary (lock contention)         Voluntary (called wait/join/park)
// Trying to ACQUIRE lock               ALREADY had lock, RELEASED it
// Auto-resumes when lock free           Needs explicit notify/unpark
// synchronized block entry              wait()/join()/park()
// No timeout (indefinite)               Can be indefinite or timed
// Thread did NOT call wait()            Thread explicitly called wait()

// ═══ IMPORTANT: wait() RELEASES the lock! ═══
// synchronized (lock) {
//     lock.wait();   // releases lock → other threads can enter!
// }
// vs
// synchronized (lock) {
//     Thread.sleep(5000);  // does NOT release lock! Others still BLOCKED!
// }
