// ─── File: src/test/java/com/bank/states/BlockedVsWaitingTest.java ───
package com.bank.states;

import org.junit.jupiter.api.Test;
import java.util.concurrent.CountDownLatch;
import static org.assertj.core.api.Assertions.*;

class BlockedVsWaitingTest {

    // ═══ BLOCKED: thread waiting for lock ═══
    @Test
    void blocked_waitingForLock() throws InterruptedException {
        Object lock = new Object();
        CountDownLatch lockHeld = new CountDownLatch(1);

        Thread holder = new Thread(() -> {
            synchronized (lock) {
                lockHeld.countDown();
                try { Thread.sleep(5000); } catch (InterruptedException e) { }
            }
        });
        holder.start();
        lockHeld.await();

        Thread waiter = new Thread(() -> {
            synchronized (lock) { /* will be BLOCKED until holder releases */ }
        });
        waiter.start();
        Thread.sleep(100);

        assertThat(waiter.getState()).isEqualTo(Thread.State.BLOCKED);
        holder.interrupt();
        holder.join();
        waiter.join();
    }

    // ═══ WAITING: thread called wait() ═══
    @Test
    void waiting_calledWait() throws InterruptedException {
        Object lock = new Object();

        Thread waiter = new Thread(() -> {
            synchronized (lock) {
                try { lock.wait(); } catch (InterruptedException e) { }
            }
        });
        waiter.start();
        Thread.sleep(100);

        assertThat(waiter.getState()).isEqualTo(Thread.State.WAITING);

        synchronized (lock) { lock.notify(); }
        waiter.join();
    }

    // ═══ WAITING: thread called join() ═══
    @Test
    void waiting_calledJoin() throws InterruptedException {
        Thread longRunning = new Thread(() -> {
            try { Thread.sleep(5000); } catch (InterruptedException e) { }
        });
        longRunning.start();

        Thread joiner = new Thread(() -> {
            try { longRunning.join(); } catch (InterruptedException e) { }
        });
        joiner.start();
        Thread.sleep(100);

        assertThat(joiner.getState()).isEqualTo(Thread.State.WAITING);
        longRunning.interrupt();
        longRunning.join();
        joiner.join();
    }

    // ═══ wait() RELEASES lock, sleep() does NOT ═══
    @Test
    void waitReleasesLock_sleepDoesNot() throws InterruptedException {
        Object lock = new Object();
        boolean[] couldEnter = {false};

        // Thread calls wait() — releases lock
        Thread waiter = new Thread(() -> {
            synchronized (lock) {
                try { lock.wait(2000); } catch (InterruptedException e) { }
            }
        });
        waiter.start();
        Thread.sleep(100);

        // Another thread CAN enter because wait() released the lock
        Thread checker = new Thread(() -> {
            synchronized (lock) {
                couldEnter[0] = true;
                lock.notify();
            }
        });
        checker.start();
        checker.join();
        waiter.join();

        assertThat(couldEnter[0]).isTrue();  // entered! wait() released the lock!
    }
}
